-- Explicit highest-grade company ADMIN authority; preserve old requests and audit history.
CREATE OR REPLACE FUNCTION baro_highest_company_approver(actor_id INTEGER,org_id INTEGER,set_id INTEGER) RETURNS BOOLEAN LANGUAGE SQL STABLE AS $$
 SELECT EXISTS(SELECT 1 FROM "Employee" e JOIN "EmployeeGrade" g ON g.id=e."gradeId" AND g."orgId"=e."orgId" JOIN "EmployeeGradeSet" s ON s.id=g."setId" AND s."orgId"=e."orgId"
 WHERE e.id=actor_id AND e."orgId"=org_id AND e.status='ACTIVE' AND e."orgRole"='ADMIN' AND g."isActive" AND s."isActive" AND g."setId"=set_id
 AND NOT EXISTS(SELECT 1 FROM "EmployeeGrade" higher WHERE higher."orgId"=org_id AND higher."setId"=set_id AND higher."isActive" AND higher."sortOrder">g."sortOrder"));
$$;
CREATE OR REPLACE FUNCTION baro_expense_deletion_request_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'EXPENSE_DELETE_HISTORY_IMMUTABLE'; END IF;
 PERFORM id FROM "ExpenseRequest" WHERE id=NEW."requestId" AND "orgId"=NEW."orgId" FOR UPDATE;
 IF NOT baro_expense_deletion_allowed(NEW."requestId",NEW."orgId",NEW.version) THEN RAISE EXCEPTION 'EXPENSE_DELETE_NOT_AVAILABLE'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'PENDING' OR NEW."documentSnapshot"->'document'->>'id' IS DISTINCT FROM NEW."requestId"::text OR NEW."documentSnapshot"->'document'->>'version' IS DISTINCT FROM NEW.version::text THEN RAISE EXCEPTION 'EXPENSE_DELETE_INVALID_REQUEST'; END IF;
  IF NOT EXISTS(SELECT 1 FROM "Employee" e JOIN "ExpenseRequest" r ON r."orgId"=e."orgId" WHERE e.id=NEW."requestedByEmployeeId" AND e."orgId"=NEW."orgId" AND e.status='ACTIVE' AND r.id=NEW."requestId" AND (e."orgRole"='ADMIN' OR r."createdByEmployeeId"=e.id OR EXISTS(SELECT 1 FROM "ExpenseRequestApprovalStep" s WHERE s."requestId"=r.id AND s."employeeId"=e.id))) THEN RAISE EXCEPTION 'EXPENSE_DELETE_NOT_PARTICIPANT'; END IF;
  IF NOT EXISTS(SELECT 1 FROM "Employee" e JOIN "EmployeeGrade" g ON g.id=e."gradeId" AND g."orgId"=e."orgId" JOIN "EmployeeGradeSet" gs ON gs.id=g."setId" WHERE e.id=NEW."finalEmployeeId" AND e."orgId"=NEW."orgId" AND g.id=NEW."finalGradeId" AND g."setId"=NEW."gradeSetId" AND g."sortOrder"=NEW."finalGradeOrder" AND g."isActive" AND gs."isActive" AND e.id=COALESCE((SELECT s."employeeId" FROM "ExpenseRequestApprovalStep" s WHERE s."requestId"=NEW."requestId" AND s."orgId"=NEW."orgId" ORDER BY s.position DESC LIMIT 1),(SELECT r."createdByEmployeeId" FROM "ExpenseRequest" r WHERE r.id=NEW."requestId" AND r."orgId"=NEW."orgId"))) THEN RAISE EXCEPTION 'EXPENSE_DELETE_FINAL_GRADE_REQUIRED'; END IF;
 ELSE
  IF OLD.status<>'PENDING' OR NEW.status NOT IN ('APPROVED','REJECTED') OR (to_jsonb(NEW)-ARRAY['status','decidedByEmployeeId','decisionReason','decidedAt']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','decidedByEmployeeId','decisionReason','decidedAt']) THEN RAISE EXCEPTION 'EXPENSE_DELETE_HISTORY_IMMUTABLE'; END IF;
  IF NOT EXISTS(SELECT 1 FROM "Employee" a JOIN "EmployeeGrade" g ON g.id=a."gradeId" AND g."orgId"=a."orgId" JOIN "EmployeeGradeSet" gs ON gs.id=g."setId" JOIN "Employee" f ON f.id=NEW."finalEmployeeId" AND f."orgId"=a."orgId" JOIN "EmployeeGrade" fg ON fg.id=f."gradeId" AND fg."orgId"=f."orgId" WHERE a.id=NEW."decidedByEmployeeId" AND a."orgId"=NEW."orgId" AND a.status='ACTIVE' AND a."orgRole"='ADMIN' AND g."isActive" AND gs."isActive" AND g."setId"=NEW."gradeSetId" AND f."gradeId"=NEW."finalGradeId" AND fg."setId"=NEW."gradeSetId" AND ((a.id<>NEW."requestedByEmployeeId" AND g."sortOrder">GREATEST(NEW."finalGradeOrder",fg."sortOrder")) OR (g."sortOrder">=GREATEST(NEW."finalGradeOrder",fg."sortOrder") AND baro_highest_company_approver(a.id,a."orgId",g."setId")))) THEN RAISE EXCEPTION 'EXPENSE_DELETE_APPROVER_REQUIRED'; END IF;
 END IF;
 RETURN NEW;
END $$;

-- Explicit self-deletion authority for new expense deletion requests only.
CREATE OR REPLACE FUNCTION baro_change_decision_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE r "ChangeApprovalRequest"%ROWTYPE; expected JSONB;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'CHANGE_HISTORY_IMMUTABLE'; END IF;
 SELECT * INTO r FROM "ChangeApprovalRequest" WHERE id=NEW."requestId" AND "orgId"=NEW."orgId" FOR UPDATE;
 expected:=r.policy->'resolvedStages'->(NEW.position-1);
 IF r.status<>'PENDING' OR (NEW."employeeId"=r."requestedByEmployeeId" AND NOT (r.menu='EXPENSE' AND r.operation='DELETE' AND r."expenseRequestId" IS NOT NULL AND COALESCE(r.policy->>'highestSelfDeletion','false')='true' AND EXISTS(SELECT 1 FROM "Employee" self_actor JOIN "EmployeeGrade" self_grade ON self_grade.id=self_actor."gradeId" AND self_grade."orgId"=self_actor."orgId" WHERE self_actor.id=NEW."employeeId" AND self_actor."orgId"=r."orgId" AND baro_highest_company_approver(self_actor.id,self_actor."orgId",self_grade."setId")))) OR expected->>'employeeId' IS DISTINCT FROM NEW."employeeId"::text OR NEW.position<>(SELECT count(*)+1 FROM "ChangeApprovalDecision" WHERE "requestId"=r.id) OR EXISTS(SELECT 1 FROM "ChangeApprovalDecision" WHERE "requestId"=r.id AND decision<>'APPROVED') OR NOT EXISTS(SELECT 1 FROM "Employee" e LEFT JOIN "EmployeeGrade" g ON g.id=e."gradeId" AND g."orgId"=e."orgId" LEFT JOIN "EmployeeGradeSet" gs ON gs.id=g."setId" WHERE e.id=NEW."employeeId" AND e."orgId"=NEW."orgId" AND e.status::text='ACTIVE' AND e."orgRole"::text=expected->>'role' AND (expected->>'gradeId' IS NULL OR e."gradeId"::text=expected->>'gradeId' AND g."isActive" AND gs."isActive")) THEN RAISE EXCEPTION 'CHANGE_APPROVER_REQUIRED'; END IF;
 RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION baro_change_request_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'CHANGE_HISTORY_IMMUTABLE'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'PENDING' OR NEW.result IS NOT NULL OR jsonb_typeof(NEW.policy->'resolvedStages') IS DISTINCT FROM 'array' OR jsonb_array_length(NEW.policy->'resolvedStages')=0 OR NEW.policy->>'menu' IS DISTINCT FROM NEW.menu OR NEW.policy->>'operation' IS DISTINCT FROM NEW.operation OR NOT EXISTS(SELECT 1 FROM "Employee" WHERE id=NEW."requestedByEmployeeId" AND "orgId"=NEW."orgId" AND status::text='ACTIVE' AND "orgRole"::text IN ('ADMIN','ACCOUNTANT','OPERATOR')) THEN RAISE EXCEPTION 'CHANGE_INVALID_REQUEST'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.policy->'resolvedStages') s WHERE (s->>'employeeId'=NEW."requestedByEmployeeId"::text AND NOT (NEW.menu='EXPENSE' AND NEW.operation='DELETE' AND NEW."expenseRequestId" IS NOT NULL AND COALESCE(NEW.policy->>'highestSelfDeletion','false')='true' AND EXISTS(SELECT 1 FROM "Employee" self_actor JOIN "EmployeeGrade" self_grade ON self_grade.id=self_actor."gradeId" AND self_grade."orgId"=self_actor."orgId" WHERE self_actor.id=NEW."requestedByEmployeeId" AND self_actor."orgId"=NEW."orgId" AND baro_highest_company_approver(self_actor.id,self_actor."orgId",self_grade."setId")))) OR NOT EXISTS(SELECT 1 FROM "Employee" e WHERE e.id::text=s->>'employeeId' AND e."orgId"=NEW."orgId" AND e.status::text='ACTIVE' AND e."orgRole"::text=s->>'role' AND (s->>'gradeId' IS NULL OR e."gradeId"::text=s->>'gradeId'))) THEN RAISE EXCEPTION 'CHANGE_INVALID_REQUEST'; END IF;
  IF (SELECT count(*) FROM jsonb_array_elements(NEW.policy->'resolvedStages'))<>(SELECT count(DISTINCT s->>'employeeId') FROM jsonb_array_elements(NEW.policy->'resolvedStages') s) THEN RAISE EXCEPTION 'CHANGE_INVALID_REQUEST'; END IF;
  IF NEW."expenseRequestId" IS NOT NULL AND (NEW.menu<>'EXPENSE' OR NEW."sourceKind"<>'request' OR NEW."sourceId"<>NEW."expenseRequestId"::text OR NOT EXISTS(SELECT 1 FROM "ExpenseRequest" WHERE id=NEW."expenseRequestId" AND "orgId"=NEW."orgId" AND version=NEW."sourceVersion" AND "deletedAt" IS NULL)) THEN RAISE EXCEPTION 'CHANGE_INVALID_SOURCE'; END IF;
  IF NEW."ledgerEntryId" IS NOT NULL AND (NEW.menu<>'BANK_LEDGER' OR NEW."sourceKind"<>'ledger' OR NEW."sourceId"<>NEW."ledgerEntryId" OR NOT EXISTS(SELECT 1 FROM "BankLedgerEntry" WHERE id=NEW."ledgerEntryId" AND "orgId"=NEW."orgId" AND "voidedAt" IS NULL)) THEN RAISE EXCEPTION 'CHANGE_INVALID_SOURCE'; END IF;
  IF NEW."legacyCostId" IS NOT NULL AND (NEW.menu<>'EXPENSE' OR NEW.operation<>'UPDATE' OR NEW."sourceKind"<>'cost' OR NEW."sourceId"<>NEW."legacyCostId" OR NOT EXISTS(SELECT 1 FROM "PartnerTransactionCost" WHERE id=NEW."legacyCostId" AND "orgId"=NEW."orgId")) THEN RAISE EXCEPTION 'CHANGE_INVALID_SOURCE'; END IF;
  IF NEW."legacyRecordId" IS NOT NULL AND (NEW.menu<>'EXPENSE' OR NEW.operation<>'UPDATE' OR NEW."sourceKind"<>'legacy' OR NEW."sourceId"<>NEW."legacyRecordId"::text OR NOT EXISTS(SELECT 1 FROM "OutsourcedWorkRecord" WHERE id=NEW."legacyRecordId" AND "orgId"=NEW."orgId")) THEN RAISE EXCEPTION 'CHANGE_INVALID_SOURCE'; END IF;
 ELSE
  IF (to_jsonb(NEW)-ARRAY['status','decidedByEmployeeId','decisionReason','decidedAt','appliedAt','result']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','decidedByEmployeeId','decisionReason','decidedAt','appliedAt','result']) THEN RAISE EXCEPTION 'CHANGE_HISTORY_IMMUTABLE'; END IF;
  IF OLD.status='APPROVED' AND NEW.status='APPROVED' AND OLD.result IS NULL AND NEW.result IS NOT NULL AND (to_jsonb(NEW)-'result')=(to_jsonb(OLD)-'result') THEN RETURN NEW; END IF;
  IF OLD.status<>'PENDING' OR NEW.status NOT IN ('APPROVED','REJECTED') OR (NEW."decidedByEmployeeId"=NEW."requestedByEmployeeId" AND NOT (NEW.menu='EXPENSE' AND NEW.operation='DELETE' AND NEW."expenseRequestId" IS NOT NULL AND COALESCE(NEW.policy->>'highestSelfDeletion','false')='true' AND EXISTS(SELECT 1 FROM "Employee" self_actor JOIN "EmployeeGrade" self_grade ON self_grade.id=self_actor."gradeId" AND self_grade."orgId"=self_actor."orgId" WHERE self_actor.id=NEW."decidedByEmployeeId" AND self_actor."orgId"=NEW."orgId" AND baro_highest_company_approver(self_actor.id,self_actor."orgId",self_grade."setId")))) OR NOT EXISTS(SELECT 1 FROM "ChangeApprovalDecision" d WHERE d."requestId"=NEW.id AND d."employeeId"=NEW."decidedByEmployeeId" AND d.decision=NEW.status AND d.position=(SELECT max(position) FROM "ChangeApprovalDecision" WHERE "requestId"=NEW.id)) THEN RAISE EXCEPTION 'CHANGE_INVALID_DECISION'; END IF;
  IF NEW.status='APPROVED' AND (jsonb_array_length(NEW.policy->'resolvedStages')<>(SELECT count(*) FROM "ChangeApprovalDecision" WHERE "requestId"=NEW.id AND decision='APPROVED')) THEN RAISE EXCEPTION 'CHANGE_INVALID_DECISION'; END IF;
 END IF;
 RETURN NEW;
END $$;
